        V("paglalaro-l38", "paglalarô", "playing", say="pag-la-la-roQ", group="gerunds", note="From maglarô (mag- verb)"),
        V("pagtatanim-l38", "pagtataním", "planting", say="pag-ta-ta-NIM", group="gerunds", note="From magtaním (mag- verb)"),
        V("pagbasa-l38", "pagbása", "reading", say="pag-BA-sa", group="gerunds", note="From basáhin (-in verb)"),
        V("pagtawag-l38", "pagtáwag", "[act of] calling", say="pag-TA-wag", group="gerunds", note="From tawágin (-in verb)"),
        V("pakikihiram-l38", "pakíkihirám", "borrowing", say="pa-KI-ki-hi-RAM", group="gerunds", note="From pakihirám (paki- verb)"),
        V("pakikisulat-l38", "pakíkisúlat", "writing", say="pa-KI-ki-SU-lat", group="gerunds", note="From pakisúlat (paki- verb). In the example it means a request that someone write."),
        V("pagligo-l38", "pagligò", "bathing", say="pag-LI-goQ", group="gerunds", note="From maligò (ma- verb, an action)"),
        V("pagkagalit-l38", "pagkagálit", "being angry; anger", say="pag-ka-GA-lit", group="gerunds", note="From magálit (ma- verb, a feeling)"),
        V("pagtatawa-l38", "pagtatawa", "laughing", group="gerunds", note="From tawanan (-an verb)"),
        V("paghuhugas-l38", "paghuhugas", "washing", group="gerunds", note="From hugasan (-an verb). The book also writes paghuhúgas."),
        V("umibig-l38", "umíbig", "to love", say="u-MI-big", pos="verb", group="verbs", note="The book also writes umibig."),
        V("maglakbay-l38", "maglakbáy", "to travel", say="mag-lak-BAY", pos="verb", group="verbs"),
        V("tugtugin-l38", "tugtugín", "to play an instrument", say="tug-tu-GIN", pos="verb", group="verbs"),
        V("patungong-m38", "patungong", "for (heading to)", pos="other", group="more", note="From: Siyá ay umalís patungong Estados Unidos = He left for the United States."),
        V("ikinalungkot-m38", "ikinalungkót", "made (me) sad", say="i-ki-na-lung-KOT", pos="verb", group="more", note="From: Ang kanyáng pag-alís ay ikinalungkót ko = His departure made me sad."),
        V("mahirap-m38", "mahirap", "difficult; tough", pos="adj", group="more", note="From: Ang pagtataním ng hasmín ay mahirap = Planting jasmine is difficult; Ang paghuhúgas ng pinggán ay mahirap na trabaho = Washing dishes is a tough job. Lesson 4 prints mahírap (poor; difficult)."),
        V("trabaho-m38", "trabaho", "job", pos="noun", group="more", note="From the lesson's vocabulary list. Lesson 12 prints trabáho."),
